create or replace function public.agendar_proxima_analise(p_cadeia integer default 0) returns bigint language plpgsql security definer set search_path = '' as $funcao$ declare v_token text; v_id bigint; begin select robo_token into v_token from public.segredos_sistema where id = 1; if v_token is null then return null; end if; select net.http_post(url := 'https://emvrcosuacstypsjampb.supabase.co/functions/v1/analisar-publicacoes', headers := jsonb_build_object('Content-Type', 'application/json', 'x-robo-token', v_token), body := jsonb_build_object('origem', 'cron', 'limite', 20, 'cadeia', greatest(coalesce(p_cadeia, 0), 0))) into v_id; return v_id; end $funcao$